=You are a world-class market research and SEO analyst. Your task is to deconstruct a seed keyword into its fundamental components to drive a keyword research strategy.

Deconstruct the user's seed keyword: "{{ $json.seed_keyword }}"
Analyze the keyword and return a JSON object with the following structure:
{
  "core_concepts": [
    "A list of 3-5 primary underlying themes or topics. What is the user REALLY interested in?"
  ],
  "user_personas": [
    "A list of 3-5 distinct user types who would search for this term. Who are they?"
  ],
  "user_motivations": [
    "A list of 3-5 key drivers or goals behind the search. What do they want to achieve?"
  ]
}

Do not include any text, explanation, or markdown formatting before or after the JSON object.

parameters.jsCode:
// This is the final, correct parser for the /keyword_ideas/live endpoint.

// Get the successful API response.
const apiResponse = $input.item.json;

// Define the clean object we want to create.
const cleanOutput = {
    keyword: "No ideas found",
    search_volume: 0,
    keyword_difficulty: 1.0 // Default to max difficulty
};

// Safely navigate to the INNER list of keyword items returned by the API.
const discoveredItems = apiResponse?.tasks?.[0]?.result?.[0]?.items;

// If the API returned a list of new ideas, process the first one.
if (discoveredItems && discoveredItems.length > 0) {
    const firstIdea = discoveredItems[0];

    // We will use the keyword from the new idea.
    cleanOutput.keyword = firstIdea.keyword;

    // Safely get the search volume for the new idea.
    if (firstIdea.keyword_info) {
        cleanOutput.search_volume = firstIdea.keyword_info.search_volume || 0;
    }

    // This is our robust logic to find the difficulty score from multiple possible locations.
    let foundDifficulty = null;
    if (firstIdea.keyword_info?.competition !== null && firstIdea.keyword_info?.competition !== undefined) {
        foundDifficulty = firstIdea.keyword_info.competition;
    } else if (firstIdea.keyword_properties?.keyword_difficulty !== null && firstIdea.keyword_properties?.keyword_difficulty !== undefined) {
        foundDifficulty = firstIdea.keyword_properties.keyword_difficulty / 100.0; // Normalize
    } else if (firstIdea.keyword_info?.competition_level) {
        const level = firstIdea.keyword_info.competition_level;
        if (level === 'LOW') foundDifficulty = 0.3;
        else if (level === 'MEDIUM') foundDifficulty = 0.6;
        else if (level === 'HIGH') foundDifficulty = 0.9;
    }

    if (foundDifficulty !== null) {
        cleanOutput.keyword_difficulty = foundDifficulty;
    }
}

// Return the final, clean checkpoint object.
return cleanOutput;

const items = $input.all();

items.forEach(item => {
  const volume = item.json.search_volume;
  const difficulty = item.json.keyword_difficulty * 100;

  item.json.opportunityScore = (volume * volume) / (difficulty + 1);
});

items.sort((a, b) => b.json.opportunityScore - a.json.opportunityScore);

return items.slice(0, 50);

const keywordString = $input.item.json.message.content;

const keywordsArray = keywordString.split('\n');

return keywordsArray.map(keyword => {
  const trimmedKeyword = keyword.trim();

  if (trimmedKeyword) {
    return {
      json: {
        "keyword": trimmedKeyword
      }
    };
  }
}).filter(Boolean);
